Definition fs_set (Σ : rtsA) (k : nat) (f : fsst) (fr : list (Z * nat)) : rtsA :=
  mkRtsA (lay Σ) (pr Σ) (ca Σ) (ca_init Σ) (sec Σ) (sec_nres Σ) (aw Σ) (ql Σ) (qg Σ) (dep Σ)
    (match k with 0%nat => f | _ => fs0 Σ end) (match k with 1%nat => f | _ => fs2 Σ end)
    (match k with 6%nat => f | _ => fs4 Σ end) (match k with 2%nat => f | _ => fs1 Σ end) (match k with 3%nat => f | _ => fc3 Σ end) (match k with 4%nat => f | _ => fc4 Σ end) (match k with 7%nat => f | _ => fc7 Σ end) (ia_init Σ) (credit Σ) (live Σ) fr.

Definition fs_release (Σ : rtsA) (k : nat) (p : Z) (fr : list (Z * nat)) : rtsA :=
  fs_set Σ k (mkFs (fss_hint (fs_of Σ k)) (upd (fss_flags (fs_of Σ k)) (Z.to_nat p) 0)) fr.

Lemma fs_of_set : forall Σ k f fr k', (k = 0 \/ k = 1 \/ k = 6 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 7)%nat -> (k' = 0 \/ k' = 1 \/ k' = 6 \/ k' = 2 \/ k' = 3 \/ k' = 4 \/ k' = 7)%nat ->
  fs_of (fs_set Σ k f fr) k' = if Nat.eqb k k' then f else fs_of Σ k'.
